SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @R varchar(20)='$(RunToken)',@M int=TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion'));IF '$(DemoId)'<>'CON-009' OR '$(TargetDatabase)'<>N'SQLPERF_LAB_CON009_'+@R THROW 51000,'FAIL_CONTRACT: CON-009-Zielkennung ist ungueltig.',1;IF '$(ConfirmIsolatedLab)'<>'1' BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_ISOLATION_REQUIRED';RETURN;END;IF @M NOT BETWEEN 15 AND 17 BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_VERSION';RETURN;END;IF HAS_PERMS_BY_NAME(NULL,NULL,'CREATE ANY DATABASE')<>1 BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_PERMISSION';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
